theorem kadiri_laplace_full_strip_weight_integrable_of_continuous {ψ : ℝ → ℂ}
    (hψ : Continuous ψ) {b σ : ℝ}
    (hσlo : -b < σ) (hσhi : σ < 1 + b)
    (hψ_decay : (fun x : ℝ ↦ ψ x * exp ((x : ℂ) / 2))
        =O[Filter.cocompact ℝ] fun x : ℝ ↦ Real.exp (-(1/2 + b) * |x|)) :
    Integrable (fun y : ℝ => exp ((σ : ℂ) * (y : ℂ)) * ψ y)

theorem kadiri_laplace_exp_differentiableOn_full_strip {φ : ℝ → ℂ}
    (hφ : ContDiff ℝ 1 φ) {b : ℝ}
    (hφ_decay : (fun x : ℝ ↦ φ x * exp ((x : ℂ) / 2))
        =O[Filter.cocompact ℝ] fun x : ℝ ↦ Real.exp (-(1/2 + b) * |x|)) :
    DifferentiableOn ℂ
      (fun s : ℂ => ∫ y : ℝ, φ y * exp (s * (y : ℂ)) ∂volume)
      {s : ℂ | -b < s.re ∧ s.re < 1 + b}

theorem kadiri_laplace_exp_meromorphicOn_full_strip {φ : ℝ → ℂ}
    (hφ : ContDiff ℝ 1 φ) {b : ℝ}
    (hφ_decay : (fun x : ℝ ↦ φ x * exp ((x : ℂ) / 2))
        =O[Filter.cocompact ℝ] fun x : ℝ ↦ Real.exp (-(1/2 + b) * |x|)) :
    MeromorphicOn
      (fun s : ℂ => ∫ y : ℝ, φ y * exp (s * (y : ℂ)) ∂volume)
      {s : ℂ | -b < s.re ∧ s.re < 1 + b}

theorem integral_exp_mul_I_scaled (a T : ℝ) :
    ∫ t in (-T)..T, Complex.exp (((t * a : ℝ) : ℂ) * I) =
      if a = 0 then (2 * T : ℂ) else (2 * Real.sin (T * a) : ℂ) / (a : ℂ)

lemma ae_restrict_norm_phi_le_of_forall_mem {A B : ℝ} (hAB : A ≤ B) {g : ℝ → ℝ}
    (hg : ∀ t, 0 ≤ g t) (h : ∀ t ∈ Set.Icc A B, φ t ≤ g t) :
    (fun t : ℝ => ‖φ t‖) ≤ᶠ[ae (volume.restrict (Set.uIoc A B))] fun t => ‖g t‖

lemma log_norm_one_sub_div_ge_neg_phi {u a : ℂ} {r : ℝ}
    (hur : ‖u‖ = r) (ha : a ≠ 0) (hr : r ≠ ‖a‖) :
    Real.log ‖(1 : ℂ) - u / a‖ ≥ -φ (r / ‖a‖)

lemma intervalIntegrable_sqrt_two_div_abs_one_sub_dyadic_middle {A : ℝ}
    (hA_lower : (1 / 4 : ℝ) ≤ A) (hA_upper : A ≤ (2 : ℝ)) :
    IntervalIntegrable (fun t : ℝ => Real.sqrt (2 / |1 - t|)) volume A (2 * A)

lemma intervalIntegrable_phi_dyadic_middle {A : ℝ}
    (hA_lower : (1 / 4 : ℝ) ≤ A) (hA_upper : A ≤ (2 : ℝ)) :
    IntervalIntegrable φ volume A (2 * A)

lemma integral_sqrt_two_div_abs_one_sub_le_K_dyadic_middle {A : ℝ}
    (hA_lower : (1 / 4 : ℝ) ≤ A) (hA_upper : A ≤ (2 : ℝ)) :
    (∫ (t : ℝ) in A..(2 * A), Real.sqrt (2 / |1 - t|) ∂volume) ≤ K

lemma integral_phi_le_Cφ_mul_middle {A : ℝ}
    (hA_lower : (1 / 4 : ℝ) ≤ A) (hA_upper : A ≤ (2 : ℝ)) :
    (∫ (t : ℝ) in A..(2 * A), φ t ∂volume) ≤ Cφ * A

theorem meromorphicOrderAt_le_deriv_add_one {f : ℂ → ℂ} {x : ℂ}
    (hf : MeromorphicAt f x) (hntop : meromorphicOrderAt f x ≠ ⊤) :
    meromorphicOrderAt f x ≤ meromorphicOrderAt (deriv f) x + 1

lemma kadiri_digamma_half_poles {s : ℂ} {T : ℝ}
    (hsim : (s / 2).im = T / 2) (hT : 1 ≤ T) :
    ∀ n : ℕ, s / 2 ≠ -(n : ℂ)

lemma kadiri_norm_inv_half_le_two {s : ℂ} {T : ℝ}
    (hsim : (s / 2).im = T / 2) (hT : 1 ≤ T) :
    ‖(s / 2)⁻¹‖ ≤ (2 : ℝ)

lemma kadiri_digamma_half_shift {s : ℂ} {T : ℝ}
    (hsim : (s / 2).im = T / 2) (hT : 1 ≤ T) :
    digamma (s / 2) = digamma ((s + 2) / 2) - (s / 2)⁻¹

lemma divisor_support_inter_compact_finite (f : 𝕜 → E) {U K : Set 𝕜}
    (hK : IsCompact K) (hKU : K ⊆ U) :
    (K ∩ (MeromorphicOn.divisor f U).support).Finite

lemma exists_ball_inter_divisor_support_eq_singleton {f : 𝕜 → E} (z₀ : 𝕜)
    (hz₀ : z₀ ∈ (MeromorphicOn.divisor f (Set.univ : Set 𝕜)).support) :
    ∃ ε > 0, Metric.ball z₀ ε ∩ (MeromorphicOn.divisor f (Set.univ : Set 𝕜)).support = {z₀}

lemma exists_seq_eq_range_divisor_support [HereditarilyLindelofSpace 𝕜] {f : 𝕜 → E} {U : Set 𝕜}
    (hne : (MeromorphicOn.divisor f U).support.Nonempty) :
    ∃ a : ℕ → 𝕜, (MeromorphicOn.divisor f U).support = Set.range a

theorem degree_derivative_le_zero_of_degree_le_one {P : Polynomial ℂ}
    (hP : P.degree ≤ 1) :
    P.derivative.degree ≤ 0

theorem eval_derivative_eq_eval_derivative_zero_of_degree_le_one {P : Polynomial ℂ}
    (hP : P.degree ≤ 1) (z : ℂ) :
    Polynomial.eval z P.derivative = Polynomial.eval 0 P.derivative

lemma HasDerivAt.of_hasDerivAt_ofReal_comp {z : ℝ} {f : ℝ → ℝ} {u : ℂ}
    (hf : HasDerivAt (fun y ↦ (f y : ℂ)) u z) :
    ∃ u' : ℝ, u = u' ∧ HasDerivAt f u' z

lemma hasProd_inv_unconditional {α : Type} {fac : α → ℂ} {F : ℂ}
    (hfac : HasProd fac F (SummationFilter.unconditional α)) (hF : F ≠ 0) :
    HasProd (fun x => (fac x)⁻¹) (F⁻¹) (SummationFilter.unconditional α)

lemma hasProd_norm_inv_unconditional {α : Type} {fac : α → ℂ} {F : ℂ}
    (hfac : HasProd fac F (SummationFilter.unconditional α)) (hF : F ≠ 0) :
    HasProd (fun x => ‖(fac x)⁻¹‖) ‖F⁻¹‖ (SummationFilter.unconditional α)
